const RECORD_COUNT = 1000;
const ITERATIONS = 100;

// Generate deterministic input without depending on filesystem or random APIs.
const records = [];
for (let i = 0; i < RECORD_COUNT; i++) {
  records.push({ id: i, name: "item-" + String(i), amount: i % 100, active: i % 2 === 0 });
}
const input = JSON.stringify(records);

let checksum = 0;
for (let iteration = 0; iteration < ITERATIONS; iteration++) {
  const parsed = JSON.parse(input);
  const selected = [];
  let total = 0;
  for (let i = 0; i < parsed.length; i++) {
    const record = parsed[i];
    if (record.active) {
      total += record.amount;
      selected.push({ id: record.id, label: record.name.toUpperCase() });
    }
  }
  const output = JSON.stringify({ total: total, items: selected });
  checksum += output.length;
}

// Make the result observable, with only one console write per process.
console.log(checksum);

// 200,000 updates across 256 objects and 8 non-index property names.
// Keep the workload and checksum identical across language variants.
const keys = ["a", "b", "c", "d", "e", "f", "g", "h"];
const objects = [];
for (let i = 0; i < 256; i++) {
  objects.push({ a: 0, b: 0, c: 0, d: 0, e: 0, f: 0, g: 0, h: 0 });
}
let checksum = 0;
for (let i = 0; i < 200000; i++) {
  const object = objects[i % 256];
  const key = keys[Math.floor(i / 256) % 8];
  const value = i % 1024;
  object[key] = value;
  checksum += object[key];
  object[key] = 0;
  // Observe removal/reset, so silently ignoring it produces a wrong checksum.
  // checksum += object[key] === undefined ? 1 : object[key] === 0 ? 1 : 0;
  const objectValue = object[key];
  if (objectValue === undefined) {
    checksum += 1;
  } else if (objectValue === 0) {
    checksum += 1;
  }
}
console.log(checksum);

